"""The method check steps (TRAIN-06, AD-09): PL-01 steps 2, 3, 6 and PL-03 step 5."""

from collections.abc import Mapping, Sequence
from typing import cast

import numpy as np

from rllab.core.types import Array, Box
from rllab.methods import Learner, MethodConfig, Transition, make_learner
from rllab.train.types import CheckFailedError, CheckResult, RunConfig
from rllab.worlds import CheckWorld, make

CHECK_WORLDS: Mapping[str, str] = {"dqn": "check-discrete", "ppo": "check-continuous"}
CHECK_BUDGET = 3_000  # world steps each method trains on its check world
PASS_AGREEMENT = 0.95  # TRAIN-06's bar
BOX_TOLERANCE = 0.1  # per dimension, for `Box` actions (worlds.CheckWorld)


def check_plan(configs: Sequence[RunConfig]) -> dict[str, MethodConfig]:
    """Each distinct team method, keyed by method name, with `check_settings` applied."""
    plan: dict[str, MethodConfig] = {}
    for config in configs:
        for team_method in config.methods.values():
            if team_method.method in plan:
                continue
            overrides = config.check_settings.get(team_method.method, {})
            settings = {**team_method.settings, **overrides}
            plan[team_method.method] = MethodConfig(team_method.method, settings)
    return plan


def train_checks(plan: Mapping[str, MethodConfig], seed: int) -> dict[str, Learner]:
    """A learner per method, trained on its check world for the fixed check budget."""
    children = np.random.SeedSequence(seed).spawn(len(plan))
    return {
        method: _train_check(config, np.random.default_rng(child))
        for (method, config), child in zip(plan.items(), children, strict=True)
    }


def score_checks(
    learners: Mapping[str, Learner], plan: Mapping[str, MethodConfig]
) -> list[CheckResult]:
    """Per method, the share of check-world states where `policy().act` is the best action."""
    results = []
    for method in plan:
        world = _check_world(method)
        agreement = _agreement(world, learners[method])
        results.append(
            CheckResult(method, world.spec.world, agreement, agreement >= PASS_AGREEMENT)
        )
    return results


def require_pass(results: Sequence[CheckResult]) -> list[CheckResult]:
    """`results` unchanged if all passed; `CheckFailedError` on the first failure."""
    for result in results:
        if not result.passed:
            raise CheckFailedError(result)
    return list(results)


def _check_world(method: str) -> CheckWorld:
    # `make` is typed to return a `World`; the check-world names build `CheckWorld`s.
    return cast(CheckWorld, make(CHECK_WORLDS[method]))


def _train_check(config: MethodConfig, rng: np.random.Generator) -> Learner:
    """`config`'s learner, stepped `CHECK_BUDGET` world steps on its check world."""
    world = _check_world(config.method)
    learner = make_learner(config, world.spec, world.spec.teams[0].name, rng)
    step = world.reset(_episode_seed(rng))
    for _ in range(CHECK_BUDGET):
        actions = learner.act(step.obs, rng)
        after = world.step(actions)
        learner.observe(
            Transition(
                obs=step.obs,
                actions=actions,
                rewards=after.rewards,
                next_obs=after.obs,
                done=after.done,
                truncated=after.truncated,
                active=step.active,
            )
        )
        ended = after.done or after.truncated
        step = world.reset(_episode_seed(rng)) if ended else after
    return learner


def _episode_seed(rng: np.random.Generator) -> int:
    return int(rng.integers(2**31))


def _agreement(world: CheckWorld, learner: Learner) -> float:
    """Share of `world.states()` where the frozen policy picks `world.best_actions()`."""
    policy = learner.policy()
    rng = np.random.default_rng(0)  # the policy is deterministic; `act` still takes a generator
    best = world.best_actions()
    chosen = np.stack([policy.act(state[np.newaxis], rng)[0] for state in world.states()])
    return float(np.mean(_matches(chosen, best, isinstance(world.spec.action, Box))))


def _matches(chosen: Array, best: Array, box: bool) -> Array:
    if box:
        diff = np.abs(chosen - best).reshape(len(best), -1)
        return np.all(diff <= BOX_TOLERANCE + 1e-9, axis=1)
    return np.asarray(chosen == best)

