"""The method check steps: check_plan, train_checks, score_checks and require_pass."""

import runpy
from pathlib import Path

import numpy as np
import pytest

from rllab.methods import MethodConfig
from rllab.train import check
from rllab.train.types import CheckFailedError, CheckResult

C = runpy.run_path(str(Path(__file__).parents[2] / "contracts" / "contracts.py"))


def snake_config():
    return C["sample"]("train.RunConfig", "snake_default")


def prey_config():
    return C["sample"]("train.RunConfig", "prey_two_methods")


class TablePolicy:
    """Acts by looking each one-agent observation up in `table` (state bytes to action)."""

    def __init__(self, states, actions) -> None:
        self.table = {s.tobytes(): a for s, a in zip(states, actions, strict=True)}

    def act(self, obs, rng):
        return np.asarray([self.table[obs[0].tobytes()]])


class FrozenLearner:
    """A learner whose frozen policy is `policy`; it never trains."""

    def __init__(self, policy) -> None:
        self._policy = policy

    def act(self, obs, rng):
        return self._policy.act(obs, rng)

    def observe(self, t) -> None:
        raise AssertionError("scoring must not train the learner")

    def policy(self):
        return self._policy

    def state_dict(self):
        return {}


class AlwaysRight:
    """A corridor learner that always steps right and keeps what it observes."""

    def __init__(self) -> None:
        self.observed = []

    def act(self, obs, rng):
        return np.asarray([1])

    def observe(self, t) -> None:
        self.observed.append(t)

    def policy(self):
        return self

    def state_dict(self):
        return {}


# ------------------------------------------------------------------------------ check_plan
def test_check_plan_applies_the_dqn_check_settings_over_the_run_settings():
    plan = check.check_plan([snake_config()])
    assert list(plan) == ["dqn"]
    assert plan["dqn"].method == "dqn"
    assert plan["dqn"].settings == {
        "lr": 0.001,
        "gamma": 0.99,
        "hidden": 16,
        "epsilon_start": 1.0,
        "epsilon_end": 0.05,
        "epsilon_decay_steps": 500,
    }
    C["validate"](C["encode"](plan["dqn"]), C["schema"]("methods.MethodConfig"))


def test_check_plan_keeps_one_entry_per_method_from_its_first_team():
    plan = check.check_plan([prey_config(), snake_config()])
    assert list(plan) == ["ppo", "dqn"]
    assert plan["ppo"].settings["lr"] == 0.0001
    assert plan["ppo"].settings["rollout_steps"] == 256
    assert plan["dqn"].settings["hidden"] == 16


def test_check_plan_leaves_the_run_config_settings_unchanged():
    config = snake_config()
    check.check_plan([config])
    assert config.methods["snake"].settings["hidden"] == 64


# ---------------------------------------------------------------------------- train_checks
@pytest.fixture
def corridor(monkeypatch):
    """`make` serves fresh corridor doubles and `make_learner` an `AlwaysRight` learner."""
    made = {"worlds": [], "learners": [], "calls": []}

    def fake_make(name):
        world = C["double"]("worlds.CheckWorld", "two_exit_corridor")
        made["worlds"].append((name, world))
        return world

    def fake_make_learner(config, spec, team, rng):
        learner = AlwaysRight()
        made["calls"].append((config, spec.world, team))
        made["learners"].append(learner)
        return learner

    monkeypatch.setattr(check, "make", fake_make)
    monkeypatch.setattr(check, "make_learner", fake_make_learner)
    monkeypatch.setattr(check, "CHECK_BUDGET", 9)
    return made


def test_train_checks_steps_the_check_world_for_the_check_budget(corridor):
    config = MethodConfig("dqn", {"lr": 0.01})
    learners = check.train_checks({"dqn": config}, seed=3)
    assert list(learners) == ["dqn"]
    assert corridor["worlds"][0][0] == "check-discrete"
    assert corridor["calls"] == [(config, "check-discrete", "agent")]
    learner = corridor["learners"][0]
    assert learners["dqn"] is learner
    assert len(learner.observed) == 9
    assert [t.done for t in learner.observed] == [False, False, True] * 3
    assert float(learner.observed[2].rewards[0]) == 1.0
    _, world = corridor["worlds"][0]
    assert len(world.seeds) == 4  # the first reset and one after each of 3 episodes


def test_train_checks_transitions_link_each_obs_to_the_next(corridor):
    check.train_checks({"dqn": MethodConfig("dqn", {})}, seed=0)
    observed = corridor["learners"][0].observed
    assert np.array_equal(observed[0].next_obs, observed[1].obs)
    assert np.array_equal(observed[0].obs[0], [0, 0, 0, 1, 0, 0])
    assert np.array_equal(observed[3].obs, observed[0].obs)  # a reset after the exit
    assert all(int(t.actions[0]) == 1 for t in observed)


def test_train_checks_reset_seeds_follow_the_seed(corridor):
    check.train_checks({"dqn": MethodConfig("dqn", {})}, seed=5)
    check.train_checks({"dqn": MethodConfig("dqn", {})}, seed=5)
    check.train_checks({"dqn": MethodConfig("dqn", {})}, seed=6)
    first, second, other = (w.seeds for _, w in corridor["worlds"])
    assert first == second
    assert first != other


def test_train_checks_feeds_the_learner_double_its_recorded_transitions(monkeypatch):
    learner = C["double"]("methods.Learner")
    monkeypatch.setattr(check, "make", lambda name: C["double"]("core.World"))
    monkeypatch.setattr(check, "make_learner", lambda config, spec, team, rng: learner)
    monkeypatch.setattr(check, "CHECK_BUDGET", len(learner.recorded))
    learners = check.train_checks({"dqn": C["sample"]("methods.MethodConfig", "snake_dqn_defaults")}, 0)
    assert learners["dqn"] is learner
    assert len(learner.observed) == len(learner.recorded) == 10
    for got, want in zip(learner.observed, learner.recorded, strict=True):
        assert np.array_equal(got.obs, want.obs)
        assert np.array_equal(got.actions, want.actions)
        assert np.array_equal(got.rewards, want.rewards)
        assert np.array_equal(got.next_obs, want.next_obs)
        assert (got.done, got.truncated) == (want.done, want.truncated)


# ---------------------------------------------------------------------------- score_checks
def score_with(monkeypatch, case, method, actions_of):
    """`score_checks` on the `case` double, with a policy choosing `actions_of(best)`."""
    world = C["double"]("worlds.CheckWorld", case)
    monkeypatch.setattr(check, "make", lambda name: C["double"]("worlds.CheckWorld", case))
    policy = TablePolicy(world.states(), actions_of(world.best_actions()))
    results = check.score_checks(
        {method: FrozenLearner(policy)}, {method: MethodConfig(method, {})}
    )
    for result in results:
        C["validate"](C["encode"](result), C["schema"]("train.CheckResult"))
    return results


def test_score_checks_passes_a_policy_with_every_best_action(monkeypatch):
    results = score_with(monkeypatch, "two_exit_corridor", "dqn", lambda best: best)
    assert results == [CheckResult("dqn", "check-discrete", 1.0, True)]


def test_score_checks_fails_a_policy_biased_to_one_action(monkeypatch):
    results = score_with(monkeypatch, "two_exit_corridor", "dqn", np.ones_like)
    assert results == [CheckResult("dqn", "check-discrete", pytest.approx(4 / 6), False)]


def test_score_checks_accepts_box_actions_within_the_tolerance(monkeypatch):
    results = score_with(monkeypatch, "target_point", "ppo", lambda best: best + 0.09)
    assert results == [CheckResult("ppo", "check-continuous", 1.0, True)]


def test_score_checks_counts_box_actions_beyond_the_tolerance_as_wrong(monkeypatch):
    def two_off(best):
        off = best.copy()
        off[:2] += 0.2
        return off

    results = score_with(monkeypatch, "target_point", "ppo", two_off)
    assert results == [CheckResult("ppo", "check-continuous", pytest.approx(4 / 6), False)]


# ---------------------------------------------------------------------------- require_pass
def test_require_pass_returns_passing_results_unchanged():
    passing = C["sample"]("train.CheckResult", "dqn_pass")
    assert check.require_pass([passing, passing]) == [passing, passing]


def test_require_pass_raises_on_the_failing_sample():
    passing = C["sample"]("train.CheckResult", "dqn_pass")
    failing = C["sample"]("train.CheckResult", "ppo_fail_080")
    with pytest.raises(CheckFailedError) as raised:
        check.require_pass([passing, failing])
    assert raised.value.result == failing
    assert "ppo" in str(raised.value)

